17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.stereotype.Component;
21	import org.springframework.validation.Errors;
22	import org.springframework.validation.ValidationUtils;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Validates an {@link OwnerFieldsDto} as part of the {@code @Valid} pass on the owner
27	 * request body: required text fields must be present and non-blank, the telephone is
28	 * canonicalised to E.164 form and required to be a valid such number, and an optional email is
29	 * required to be syntactically valid and normalized to lower case.
30	 * <p>
31	 * Registered on the owner controller through {@code @InitBinder} so every rejected field is
32	 * recorded as a field error on the shared {@link Errors}, surfacing through the usual
33	 * bad-request handling. A valid telephone is written back to the DTO in E.164 form so it
34	 * is stored, returned and compared for duplicates as that canonical string.
35	 *
36	 * @author Vitaliy Fedoriv
37	 */
38	@Component
39	public class OwnerFieldsValidator implements Validator {
40	
41	    private static final String[] REQUIRED_FIELDS = {"firstName", "lastName", "address", "city", "telephone"};
42	
43	    private final TelephoneNormalizer telephoneNormalizer;
44	
45	    private final EmailNormalizer emailNormalizer;
46	
47	    public OwnerFieldsValidator(TelephoneNormalizer telephoneNormalizer, EmailNormalizer emailNormalizer) {
48	        this.telephoneNormalizer = telephoneNormalizer;
49	        this.emailNormalizer = emailNormalizer;
50	    }
51	
52	    @Override
53	    public boolean supports(Class<?> clazz) {
54	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
55	    }
56	
57	    @Override
58	    public void validate(Object target, Errors errors) {
59	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
60	        for (String field : REQUIRED_FIELDS) {
61	            ValidationUtils.rejectIfEmptyOrWhitespace(errors, field, "required", "must not be blank");
62	        }
63	        if (!errors.hasFieldErrors("telephone")) {
64	            normalizeTelephone(owner, errors);
65	        }
66	        normalizeEmail(owner, errors);
67	    }
68	
69	    private void normalizeTelephone(OwnerFieldsDto owner, Errors errors) {
70	        telephoneNormalizer.toE164(owner.getTelephone()).ifPresentOrElse(
71	            owner::setTelephone,
72	            () -> errors.rejectValue("telephone", "telephone.invalid",
73	                "must be a valid telephone number in E.164 form"));
74	    }
75	
76	    private void normalizeEmail(OwnerFieldsDto owner, Errors errors) {
77	        String email = owner.getEmail();
78	        if (email == null) {
79	            return;
80	        }
81	        if (emailNormalizer.isValid(email)) {
82	            owner.setEmail(emailNormalizer.normalize(email));
83	        } else {
84	            errors.rejectValue("email", "email.invalid", "must be a valid email address");
85	        }
86	    }
87	}
