23	/**
24	 * Assigns an owner's customer code on create.
25	 * <p>
26	 * The code is formatted {@code <LAST3>-<NNNN>} where {@code LAST3} is the upper-cased
27	 * first three letters of the owner's last name and {@code NNNN} is a global 4-digit
28	 * zero-padded sequence equal to one more than the current number of stored owners
29	 * (e.g. {@code "SMI-0007"}).
30	 */
31	@Component
32	public class CustomerCodeAssigner {
33	
34	    private final ClinicService clinicService;
35	
36	    public CustomerCodeAssigner(ClinicService clinicService) {
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * Assigns {@code owner}'s customer code based on its last name and the current owner
42	     * count. Call this before the owner is saved so the sequence reflects the number of
43	     * owners already stored.
44	     *
45	     * @param owner the owner being created
46	     */
47	    public void assign(Owner owner) {
48	        String lastName = owner.getLastName();
49	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
50	        long sequence = clinicService.countOwners() + 1;
51	        owner.setCustomerCode(String.format("%s-%04d", prefix, sequence));
52	    }
53	}
