18	
19	import java.util.Locale;
20	import java.util.regex.Pattern;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.service.ClinicService;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Detects, on create, whether an owner would duplicate an existing household.
28	 * <p>
29	 * Two owners share a household when they carry the same last name and the same address.
30	 * Both fields are compared leniently: surrounding whitespace is trimmed, internal runs of
31	 * whitespace are collapsed to a single space and letters are compared without regard to
32	 * case, so values that differ only in spacing or capitalisation are treated as equal.
33	 */
34	@Component
35	public class HouseholdDuplicateChecker {
36	
37	    /** Runs of whitespace collapsed to a single space before comparison. */
38	    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
39	
40	    private final ClinicService clinicService;
41	
42	    public HouseholdDuplicateChecker(ClinicService clinicService) {
43	        this.clinicService = clinicService;
44	    }
45	
46	    /**
47	     * Reports whether an already-stored owner shares {@code candidate}'s household, i.e.
48	     * has the same last name and address under the lenient comparison described above.
49	     *
50	     * @param candidate the owner being created
51	     * @return {@code true} when another owner already occupies the same household
52	     */
53	    public boolean isDuplicate(Owner candidate) {
54	        String lastName = normalize(candidate.getLastName());
55	        String address = normalize(candidate.getAddress());
56	        return clinicService.findAllOwners().stream()
57	            .anyMatch(existing -> normalize(existing.getLastName()).equals(lastName)
58	                && normalize(existing.getAddress()).equals(address));
59	    }
60	
61	    private String normalize(String value) {
62	        if (value == null) {
63	            return "";
64	        }
65	        return WHITESPACE.matcher(value.trim()).replaceAll(" ").toLowerCase(Locale.ROOT);
66	    }
67	}
