20	import java.util.regex.Pattern;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Canonicalises an owner telephone number to E.164 form.
26	 * <p>
27	 * Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
28	 * kept when present; otherwise the {@link #DEFAULT_COUNTRY_CODE default country code} is
29	 * assumed and a single leading {@code '0'} is dropped from the national digits. The result
30	 * is a {@code '+'} followed by {@link #MIN_DIGITS}-{@link #MAX_DIGITS} digits, so numbers
31	 * that differ only in formatting or in the way their country code is written are stored and
32	 * compared identically.
33	 */
34	@Component
35	public class TelephoneNormalizer {
36	
37	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
38	    public static final String DEFAULT_COUNTRY_CODE = "61";
39	
40	    /** The fewest digits a valid E.164 number carries after the {@code '+'}. */
41	    public static final int MIN_DIGITS = 8;
42	
43	    /** The most digits a valid E.164 number carries after the {@code '+'}. */
44	    public static final int MAX_DIGITS = 15;
45	
46	    /** Separators removed before interpreting the number: spaces, dashes and brackets. */
47	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
48	
49	    /**
50	     * Converts a raw telephone into its canonical E.164 representation.
51	     *
52	     * @param raw the telephone as supplied by the client, possibly {@code null}
53	     * @return the E.164 number ({@code '+'} then {@value #MIN_DIGITS}-{@value #MAX_DIGITS}
54	     *         digits), or empty when {@code raw} cannot form a valid E.164 number
55	     */
56	    public Optional<String> toE164(String raw) {
57	        if (raw == null) {
58	            return Optional.empty();
59	        }
60	        String stripped = SEPARATORS.matcher(raw).replaceAll("");
61	        String digits = stripped.startsWith("+")
62	            ? stripped.substring(1)
63	            : DEFAULT_COUNTRY_CODE + dropLeadingZero(stripped);
64	        return isValid(digits) ? Optional.of("+" + digits) : Optional.empty();
65	    }
66	
67	    private String dropLeadingZero(String national) {
68	        return national.startsWith("0") ? national.substring(1) : national;
69	    }
70	
71	    private boolean isValid(String digits) {
72	        return digits.chars().allMatch(c -> c >= '0' && c <= '9')
73	            && digits.length() >= MIN_DIGITS && digits.length() <= MAX_DIGITS;
74	    }
75	}
